 "content": "def transform(grid):
    """Fill the interiors of hollow rectangular frames and mark 3x3 ring centers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Grid background is the most common color; outlines are compact connected
    # components, so detect each object separately rather than using global bbox.
    colors = {v for row in grid for v in row}
    for color in colors:
        seen = set()
        for sr in range(h):
            for sc in range(w):
                if grid[sr][sc] != color or (sr, sc) in seen:
                    continue
                stack = [(sr, sc)]
                seen.add((sr, sc))
                comp = []
                while stack:
                    r, c = stack.pop()
                    comp.append((r, c))
                    for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                        if 0 <= rr < h and 0 <= cc < w and (rr,cc) not in seen and grid[rr][cc] == color:
                            seen.add((rr,cc))
                            stack.append((rr,cc))
                r0=min(r for r,c in comp); r1=max(r for r,c in comp)
                c0=min(c for r,c in comp); c1=max(c for r,c in comp)
                if r1-r0 < 2 or c1-c0 < 2:
                    continue
                perimeter = 2*(r1-r0+1)+2*(c1-c0-1)
                if len(comp) != perimeter:
                    continue
                if not (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and
                        all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))):
