                    fill = 7
                elif color == 3:
                    fill = 2
                elif color == 4:
                    fill = 2
                elif color == 6:
                    fill = 7
                elif color == 8:
                    fill = 7
                elif color == 9:
                    fill = 2
                elif color == 1:
                    fill = 7
                else:
                    fill = 2
                for r in range(r0+1, r1):
                    for c in range(c0+1, c1):
                        out[r][c] = fill
    # A hollow 3x3 square ring always gets a 7 in its center.
    for r in range(h-2):
        for c in range(w-2):
